const touchMCPOAuthToken = `-- name: TouchMCPOAuthToken :exec
WITH t AS (
    UPDATE mcp_oauth_tokens SET last_used_at = NOW() WHERE mcp_oauth_tokens.id = $1
    RETURNING grant_id
)
UPDATE mcp_oauth_grants SET last_used_at = NOW() WHERE mcp_oauth_grants.id = (SELECT grant_id FROM t)
`

// Last use of the token and its grant (connected apps list).
func (q *Queries) TouchMCPOAuthToken(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, touchMCPOAuthToken, id)
	return err
}

const upsertMCPOAuthGrant = `-- name: UpsertMCPOAuthGrant :one
INSERT INTO mcp_oauth_grants (user_id, client_id, organization_id, resource, scopes)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT ON CONSTRAINT uq_mcp_oauth_grants_key
DO UPDATE SET scopes = EXCLUDED.scopes, revoked_at = NULL
RETURNING id, uuid, user_id, client_id, organization_id, resource, scopes, last_used_at, revoked_at, created_at, updated_at
`

type UpsertMCPOAuthGrantParams struct {
	UserID         int64       `json:"user_id"`
	ClientID       string      `json:"client_id"`
	OrganizationID pgtype.Int8 `json:"organization_id"`
	Resource       string      `json:"resource"`
	Scopes         []string    `json:"scopes"`
}

// Consent creates the user's connected app or brings a revoked one back.
func (q *Queries) UpsertMCPOAuthGrant(ctx context.Context, arg UpsertMCPOAuthGrantParams) (McpOauthGrant, error) {
	row := q.db.QueryRow(ctx, upsertMCPOAuthGrant,
		arg.UserID,
		arg.ClientID,
		arg.OrganizationID,
		arg.Resource,
		arg.Scopes,
	)
	var i McpOauthGrant
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.UserID,
		&i.ClientID,
		&i.OrganizationID,
		&i.Resource,
		&i.Scopes,
		&i.LastUsedAt,
		&i.RevokedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const useMCPOAuthCode = `-- name: UseMCPOAuthCode :one
UPDATE mcp_oauth_codes
SET used_at = NOW(), family = $1
WHERE code_hash = $2 AND used_at IS NULL AND expires_at > NOW()
RETURNING code_hash, grant_id, client_id, user_id, organization_id, redirect_uri, code_challenge, resource, scopes, expires_at, used_at, family, created_at
`

type UseMCPOAuthCodeParams struct {
	Family   pgtype.UUID `json:"family"`
	CodeHash string      `json:"code_hash"`
}

// Marking the code used is the claim; an expired or used code returns no row.
func (q *Queries) UseMCPOAuthCode(ctx context.Context, arg UseMCPOAuthCodeParams) (McpOauthCode, error) {
	row := q.db.QueryRow(ctx, useMCPOAuthCode, arg.Family, arg.CodeHash)
	var i McpOauthCode
	err := row.Scan(
		&i.CodeHash,
		&i.GrantID,
		&i.ClientID,
		&i.UserID,
		&i.OrganizationID,
		&i.RedirectUri,
		&i.CodeChallenge,
		&i.Resource,
		&i.Scopes,
		&i.ExpiresAt,
		&i.UsedAt,
		&i.Family,
		&i.CreatedAt,
	)
	return i, err
}
